cypress_script:
describe('Mobile Viewport Product Browsing via Burger Menu', () => {
  it('should open the burger menu and display product categories', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-test="open-menu"]').click();
    cy.get('[data-test="inventory-sidebar-link"]').should('be.visible');
    cy.get('[data-test="about-sidebar-link"]').should('be.visible');
    cy.get('[data-test="close-menu"]').should('be.visible');
  });

  it('should not add a product to the cart if the burger menu is closed', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-test="close-menu"]').click();
    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-test="shopping-cart-link"]').should('not.exist');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Mobile Viewport Product Browsing via Burger Menu', () => {
  test('should open the burger menu and display product categories', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await page.click('[data-test="open-menu"]');
    await expect(page.locator('[data-test="inventory-sidebar-link"]')).toBeVisible();
    await expect(page.locator('[data-test="about-sidebar-link"]')).toBeVisible();
    await expect(page.locator('[data-test="close-menu"]')).toBeVisible();
  });

  test('should not add a product to the cart if the burger menu is closed', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await page.click('[data-test="close-menu"]');
    await page.click('[data-test="add-to-cart-sauce-labs-backpack"]');
    await expect(page.locator('[data-test="shopping-cart-link"]').count()).toBe(0);
  });
});
